inline int correction_cached(unsigned s,unsigned t,unsigned proto,int dx,int dy,unsigned nx,unsigned ny,unsigned tx,unsigned ty,unsigned code,unsigned sc,unsigned tc){
const unsigned phase=code>>8,shape=code&255,ax=dx<0?-dx:dx,ay=dy<0?-dy:dy;
int c=int(source_phase[s*120+phase])+target_phase[t*120+phase]+source_shape[s*72+shape]+target_shape[t*72+shape];
c+=int(source_x[s*4+nx/30])+target_x[t*4+tx/30]+source_y[s*11+ny/50]+target_y[t*11+ty/50];
const unsigned bx=std::min(12u,ax/10),by=std::min(22u,ay/24);
c+=int(source_dx[s*13+bx])+target_dx[t*13+bx]+source_dy[s*23+by]+target_dy[t*23+by]+source_prototype_direction[(s*32+proto)*2+(dy<0)];
(void)sc;(void)tc;
return c>=-4?(c+4)/8:-((-c+3)/8);
}
inline bool prediction_cached(uint32_t raw,unsigned source,unsigned target,int dx,int dy,unsigned nx,unsigned ny,unsigned tx,unsigned ty,unsigned code,unsigned sc,unsigned tc,uint32_t&out){
if(source>=496||target>=496||nx>=120||tx>=120||ny>=550||ty>=550||dx<-119||dx>119||dy<-549||dy>549)return false;
const int s=srb_v11_pair30_models::kSourceRow[source],t=srb_v11_pair30_models::kTargetRow[target];
const unsigned p=srb_v11_pair30_models::kTargetPrototype[target];
if(s<0||t<0||p>=32||code>>8>=120||(code&255)>=72)return false;
const int64_t v=std::max<int64_t>(0,int64_t(raw)+correction_cached(s,t,p,dx,dy,nx,ny,tx,ty,code,sc,tc));
if(uint64_t(v)>std::numeric_limits<uint32_t>::max())return false;out=uint32_t(v);return true;
}
inline void prefetch_cached(unsigned s,unsigned t,unsigned code){
#if defined(__GNUC__) || defined(__clang__)
__builtin_prefetch(source_phase+s*120+(code>>8),0,3);__builtin_prefetch(target_phase+t*120+(code>>8),0,3);
__builtin_prefetch(source_shape+s*72+(code&255),0,3);__builtin_prefetch(target_shape+t*72+(code&255),0,3);
#else
(void)s;(void)t;(void)code;
#endif
}
